const data = $input.first().json;

const cashierName = data.cashier_name || 'Kasir';
const startingCash = Number(data.starting_cash || 0);
const actualCash = Number(data.actual_cash || 0);
const expectedCash = Number(data.expected_cash || 0);
const cashDifference = Number(data.cash_difference || 0);
const cashSales = Number(data.total_cash_sales || 0);
const qrisSales = Number(data.total_qris_sales || 0);
const debtSales = Number(data.total_debt_sales || 0);
const agentProfit = Number(data.agent_profit || 0);

const totalSales = cashSales + qrisSales + debtSales;
const grandTotal = totalSales + agentProfit;

const fmt = (n) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0 }).format(n);

const openedDate = new Date(data.opened_at).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' });
const closedDate = new Date(data.closed_at).toLocaleDateString('id-ID', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
const closedTime = new Date(data.closed_at).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' });

let message = '📊 *Laporan Penutupan Sesi Kasir* 📊\n';
message += `📅 Tanggal : *${closedDate}*\n`;
message += `⏰ Waktu   : *${openedDate} - ${closedTime}*\n`;
message += `👤 Kasir   : *${cashierName}*\n`;
message += '━━━━━━━━━━━━━━━━━━━━\n\n';
message += '🏪 *Rincian Penjualan Sesi:*\n';
message += `  - 💵 Tunai (Cash) : *${fmt(cashSales)}*\n`;
message += `  - 💳 QRIS         : *${fmt(qrisSales)}*\n`;
message += `  - 🤝 Hutang (Bon) : *${fmt(debtSales)}*\n`;
message += `  *Total Omset POS : ${fmt(totalSales)}*\n\n`;
message += `📱 *Profit Agen*     : *${fmt(agentProfit)}*\n`;
message += '━━━━━━━━━━━━━━━━━━━━\n';
message += `💰 *GRAND TOTAL    : ${fmt(grandTotal)}*\n\n`;

message += '🧾 *Rekonsiliasi Kas Laci:*\n';
message += `  - 💵 Modal Awal   : *${fmt(startingCash)}*\n`;
message += `  - 📈 Uang Fisik   : *${fmt(actualCash)}*\n`;
message += `  - 📊 Ekspektasi   : *${fmt(expectedCash)}*\n`;

if (cashDifference === 0) {
  message += '  - 🟢 *Status Kas : Cocok/Pas*\n';
} else if (cashDifference > 0) {
  message += `  - 🔵 *Status Kas : Surplus ${fmt(cashDifference)}*\n`;
} else {
  message += `  - 🔴 *Status Kas : Minus ${fmt(Math.abs(cashDifference))}*\n`;
}

message += '\n✅ Laporan otomatis oleh sistem.';

return [{ json: { whatsapp_text: message } }];
